sys_script_include.script:
var IncentNowUtils = Class.create();
IncentNowUtils.prototype = {
    initialize: function() {
        this._territoryAvailable = null;
    },

    DIMENSION_BU: 'business_unit',
    DIMENSION_TERRITORY: 'territory',
    TERRITORY_EXTENSION_SCOPE: 'x_ctans_territory',
    SALES_TERRITORY_PLUGIN_ID: 'sn_sales_territory', //ServiceNow Sales Territory Management

    getQuotaByUserBusinessUnit: function(userId) {
        return this.getQuotaByUserDimension(userId);
    },

    getPlanByUserBusinessUnit: function(userId) {
        return this.getPlanByUserDimension(userId);
    },

    getUserByQuotaBusinessUnit: function(quotaId) {
        return this.getUserByQuotaDimension(quotaId);
    },

    getUserByPlanBusinessUnit: function(planId) {
        return this.getUserByPlanDimension(planId);
    },

    getQuotaByUserDimension: function(userId) {
        return this._getTargetByUserDimension(userId, 'x_ctans_incentnow_quota');
    },

    getPlanByUserDimension: function(userId) {
        return this._getTargetByUserDimension(userId, 'x_ctans_incentnow_plan');
    },

    getUserByQuotaDimension: function(quotaId) {
        return this._getUsersBySourceDimension(quotaId, 'x_ctans_incentnow_quota');
    },

    getUserByPlanDimension: function(planId) {
        return this._getUsersBySourceDimension(planId, 'x_ctans_incentnow_plan');
    },

    _getTargetByUserDimension: function(userId, targetTable) {
        var query = 'active=true';

        if (!userId)
            return query + '^sys_idISEMPTY';

        var userGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        if (!userGR.get(userId))
            return query + '^sys_idISEMPTY';

        var dimension = userGR.getValue('business_dimension');

        if (dimension == this.DIMENSION_BU) {
            var businessUnit = userGR.getValue('business_unit');
            if (!businessUnit)
                return query + '^sys_idISEMPTY';

            query += '^business_dimension=' + this.DIMENSION_BU;
            query += '^business_unit=' + businessUnit;

            return query;
        }

        if (dimension == this.DIMENSION_TERRITORY) {
            return this._getQueryFromTerritoryExtension({
                mode: 'target_by_user',
                sourceTable: 'x_ctans_incentnow_user_profile',
                sourceSysId: userGR.getUniqueValue(),
                targetTable: targetTable,
                baseQuery: query
            });
        }

        return query + '^sys_idISEMPTY';
    },

    _getUsersBySourceDimension: function(sourceId, sourceTable) {
        var query = 'active=true';

        if (!sourceId)
            return query + '^sys_idISEMPTY';

        var sourceGR = new GlideRecordSecure(sourceTable);
        if (!sourceGR.get(sourceId))
            return query + '^sys_idISEMPTY';

        var dimension = sourceGR.getValue('business_dimension');

        if (dimension == this.DIMENSION_BU) {
            var businessUnit = sourceGR.getValue('business_unit');
            if (!businessUnit)
                return query + '^sys_idISEMPTY';

            query += '^business_dimension=' + this.DIMENSION_BU;
            query += '^business_unit=' + businessUnit;

            return query;
        }

        if (dimension == this.DIMENSION_TERRITORY) {
            return this._getQueryFromTerritoryExtension({
                mode: 'users_by_source',
                sourceTable: sourceTable,
                sourceSysId: sourceGR.getUniqueValue(),
                targetTable: 'x_ctans_incentnow_user_profile',
                baseQuery: query
            });
        }

        return query + '^sys_idISEMPTY';
    },

    _getQueryFromTerritoryExtension: function(context) {

        if (!this.isTerritoryExtensionActive()) {
            return context.baseQuery + '^sys_idISEMPTY';
        }

        try {
            var resolver = new x_ctans_territory.IncentNowTerritoryResolver();
            var resolvedQuery = resolver.resolve(context);
            if (!resolvedQuery) {
                gs.warn(
                    '[IncentIQ] Territory resolver returned an empty query. ' +
                    'Mode=' + context.mode
                );
                return context.baseQuery + '^sys_idISEMPTY';
            }
            return resolvedQuery;
        } catch (e) {
            gs.warn('IncentIQ Territory resolver failed: ' + e.message);
            return context.baseQuery + '^sys_idISEMPTY';
        }
    },
    isTerritoryExtensionActive: function() {
        return this._isTerritoryExtensionActive();
    },

    _isTerritoryExtensionActive: function() {

        if (this._territoryAvailable !== null)
            return this._territoryAvailable;

        try {

            // System properties are returned as strings.
            var useTerritory = this._getProp('x_ctans_incentnow.business_dimension_territory','false') === 'true';

            // If territory functionality is disabled by configuration,
            // no need to perform additional checks.
            if (!useTerritory) {
                this._territoryAvailable = false;
                return false;
            }
            var extensionInstalled = this._isApplicationInstalled(
                this.TERRITORY_EXTENSION_SCOPE
            );
            if (!extensionInstalled) {
                this._territoryAvailable = false;
                return false;
            }

            var pluginActive = GlidePluginManager.isActive(
                this.SALES_TERRITORY_PLUGIN_ID
            );

            this._territoryAvailable = extensionInstalled && pluginActive && useTerritory;

        } catch (e) {
            gs.error(
                '[IncentIQ] Territory availability check failed: ' + e.message
            );

            this._territoryAvailable = false;
        }
        return this._territoryAvailable;
    },
    //  Property fallback only when empty/null
    _getProp: function(name, defaultValue) {

        var val = gs.getProperty(name);

        if (val === null || val === undefined || val === '') {
            return defaultValue;
        }

        return val;
    },

    _isApplicationInstalled: function(applicationScope) {
        if (!applicationScope)
            return false;
        var scopeGR = new GlideRecordSecure('sys_scope');
        scopeGR.addQuery('scope', applicationScope);
        scopeGR.setLimit(1);
        scopeGR.query();

        return scopeGR.hasNext();
    },

    getTerritoryManagers: function(territorySysId) {
        if (!territorySysId)
            return '';

        if (!this.isTerritoryExtensionActive()) {
            gs.warn(
                '[IncentIQ] Cannot retrieve Territory managers because ' +
                'Territory functionality is unavailable.'
            );

            return '';
        }

        try {
            var resolver =
                new x_ctans_territory.IncentNowTerritoryResolver();

            var managers =
                resolver.getTerritoryManagers(territorySysId);

            return managers || '';

        } catch (e) {
            gs.error(
                '[IncentIQ] Territory manager resolver failed. ' +
                'Territory=' + territorySysId +
                ', error=' + e.message
            );

            return '';
        }
    },
    type: 'IncentNowUtils'
};
